from PIL import Image
import numpy as np
blob = np.asarray(Image.open('blobmap.png').convert('L')).astype(float)/255.0
# dark blobs: blobmap value < 0.35 means locally much darker
mask = blob < 0.35
# simple connected components
lab = np.zeros_like(blob, dtype=int)
from collections import deque
H,W = mask.shape
cur=0; comps=[]
visited = np.zeros_like(mask, dtype=bool)
for y in range(0,H,2):
    for x in range(0,W,2):
        if mask[y,x] and not visited[y,x]:
            cur+=1; q=deque([(y,x)]); visited[y,x]=True
            pts=[]
            while q:
                cy,cx=q.popleft(); pts.append((cy,cx))
                for dy in(-1,0,1):
                    for dx in(-1,0,1):
                        ny,nx=cy+dy,cx+dx
                        if 0<=ny<H and 0<=nx<W and mask[ny,nx] and not visited[ny,nx]:
                            visited[ny,nx]=True; q.append((ny,nx))
            ys=[p[0] for p in pts]; xs=[p[1] for p in pts]
            area=len(pts)
            if area>400:
                comps.append((area, min(xs),min(ys),max(xs),max(ys)))
comps.sort(reverse=True)
for a,x1,y1,x2,y2 in comps[:40]:
    print(f"area={a:6d} x=[{x1/W:.3f},{x2/W:.3f}] y=[{y1/H:.3f},{y2/H:.3f}]")
EOF", "description": "Detect dark blob regions and list bounding boxes"}
